import type { CreateHost, Effect, Host, OrderView, Outcome } from '../host.ts';

interface Order {
  status: OrderView['status'];
  items: number;
  charges: number;
  refunds: number;
}

const MAX_ITEMS = 3;

const ok = (): Outcome => ({ ok: true });
const refuse = (reason: string): Outcome => ({ ok: false, reason });

const createHost: CreateHost = async () => {
  const orders = new Map<string, Order>();
  const pending = new Map<string, Effect>();
  let nextEffect = 1;

  const request = (from: string, kind: string, data: Record<string, unknown>): void => {
    const id = `effect-${nextEffect++}`;
    pending.set(id, { id, from, kind, data });
  };

  const host: Host = {
    async create(id) {
      if (orders.has(id)) return refuse('order already exists');
      orders.set(id, { status: 'draft', items: 0, charges: 0, refunds: 0 });
      return ok();
    },

    async addItem(id) {
      const o = orders.get(id);
      if (!o) return refuse('no such order');
      if (o.status !== 'draft') return refuse(`order is ${o.status}`);
      if (o.items >= MAX_ITEMS) return refuse('order is full');
      o.items++;
      return ok();
    },

    async removeItem(id) {
      const o = orders.get(id);
      if (!o) return refuse('no such order');
      if (o.status !== 'draft') return refuse(`order is ${o.status}`);
      if (o.items === 0) return refuse('order is empty');
      o.items--;
      return ok();
    },

    async place(id) {
      const o = orders.get(id);
      if (!o) return refuse('no such order');
      if (o.status !== 'draft') return refuse(`order is ${o.status}`);
      if (o.items === 0) return refuse('order is empty');
      o.status = 'placed';
      o.charges++;
      request(id, 'payment.charge', { amount: o.items });
      return ok();
    },

    async ship(id) {
      const o = orders.get(id);
      if (!o) return refuse('no such order');
      if (o.status !== 'paid') return refuse(`order is ${o.status}`);
      o.status = 'shipped';
      return ok();
    },

    async cancel(id) {
      const o = orders.get(id);
      if (!o) return refuse('no such order');
      if (o.status === 'draft') {
        o.status = 'cancelled';
        return ok();
      }
      if (o.status === 'paid') {
        o.status = 'cancelled';
        o.refunds++;
        return ok();
      }
      return refuse(`order is ${o.status}`);
    },

    async order(id) {
      const o = orders.get(id);
      return o ? { ...o } : null;
    },

    async pendingEffects() {
      return [...pending.values()].map((e) => ({ ...e, data: { ...e.data } }));
    },

    async completeEffect(effectId, outcome) {
      const e = pending.get(effectId);
      if (!e) return;
      pending.delete(effectId);
      const o = orders.get(e.from);
      if (!o || e.kind !== 'payment.charge' || o.status !== 'placed') return;
      o.status = outcome === 'ok' ? 'paid' : 'failed';
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('happy path', async () => {
  const h = await createHost();
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ ...e, id: undefined }, { id: undefined, from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 2, charges: 1, refunds: 1 });
  assert.equal((await h.ship('a')).ok, false);
  assert.equal(await h.order('zz'), null);
});

test('failed charge', async () => {
  const h = await createHost();
  await h.create('b'); await h.addItem('b'); await h.place('b');
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'failed');
  assert.equal((await h.order('b'))!.status, 'failed');
  assert.equal((await h.cancel('b')).ok, false);
  assert.equal((await h.ship('b')).ok, false);
});
EOF
