  for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel'] as const) {
    assert.equal((await h[cmd]('b')).ok, false, cmd);
  }
  assert.equal((await h.retryPayment('b')).ok, true);
  assert.deepEqual(await h.order('b'), { status: 'placed', items: 1, charges: 2, refunds: 0, held: false });
  const [e2] = await h.pendingEffects();
  assert.notEqual(e2.id, e.id);
  assert.equal(e2.kind, 'payment.charge');
  await h.completeEffect(e2.id, 'failed');
  assert.equal((await h.order('b'))!.status, 'failed');
  assert.equal((await h.retryPayment('b')).ok, false);
  assert.equal((await h.cancel('b')).ok, false);
  assert.equal((await h.ship('b')).ok, false);
});

test('retry succeeds', async () => {
